INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('torta-de-ricota', 'Torta de ricota', 'Salgados', '2009-12-08', 'Torta de ricota  Deliciosa.', '{"gema":"16% - 400g","clara":"24% - 600g","açúcar":"60% - 1500g","uvas-passas":"8% - 200g","canela-em-po":"0.2% - 5g","ricota fresca":"100% - 2500g","essência de limão":"QB","creme de confeiteiro":"20% - 500g","frutas cristalizadas":"8% - 200g"}', NULL, 'Peneire a ricota e junte a todos os ingredientes menos as claras e bata na primeira velocidade e reserve. Bata as claras na terceira velocidade e vá adicionando lentamente o restante do ingredientes.', '', 'https://imgs.search.brave.com/ylkHgSwZOh7kDw9mUAEwqRs7gT74ptGhj30SBHPDamA/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9zdGF0/aWMuaXRkZy5jb20u/YnIvaW1hZ2VzLzY0/MC00MDAvZWE0M2Fm/ZWJjZWM2MjgyMjEx/NjU2ZWY3ODg2M2Fm/YjgvMzI3MTQ5LW9y/aWdpbmFsLmpwZw', 'Torta de ricota');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('queijadinha', 'Queijadinha', 'Paes', '2009-12-08', 'Receita importada de 08_12_2009_Queijadinha.doc', '{"agua":"50% - 250g","ovos":"20% - 100g","gemas":"20% - 100g","acucar":"100% - 500g","margarina":"10% - 50g","queijo-parmesao":"100% - 500g","coco-seco-acucarado":"80% - 400g"}', NULL, 'Coloque em uma panela , o açúcar, água e a margarina e leve ao fogo       e deixe ferver, esfrie a mistura até que ela fique morna e adicione o restante dos ingredientes e espere o ponto. Forre as formas com papel antes de colocar a massa, e leve ao forno por mais ou menos 20 minutos a uma temperatura de 200 graus.', '', 'https://imgs.search.brave.com/rWMkR2_EZKEbOireJQnxFYpYXM1ZcIs1lArKH_zWPdk/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9zdGF0/aWMuaXRkZy5jb20u/YnIvaW1hZ2VzLzY0/MC00MDAvNTUxM2My/MDNkMDgyOWMyZWVh/MGFkMWMxNDI2OTZj/MDYvMzU0MjQ5LW9y/aWdpbmFsLmpwZw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('quindim-de-coco-fresco', 'Quindim de coco fresco', 'Paes', '2009-12-07', 'Receita importada de 07_12_2009_quindim_de_coco_fresco.doc', '{"Gemas":"64% - 1600g","Açúcar":"100% - 2500g","Margarina":"12% - 300g","Coco fresco":"60% - 1500g"}', NULL, 'Junte o coco e o açúcar e misture manualmente e deixe descansar por 1 hora. Coloque a margarina em uma panela e leve ao forno para derreter  e tire do fogo e acrescentando as gemas o coco fresco ralado com açúcar  misture com as mãos. Coloque a massa em  formas undadas com margarina e polvilhadas com açúcar e leve ao forno por mais ou menos 20 minutos a um temperatura    de 200 graus em banho maria.', '', 'https://imgs.search.brave.com/SLHOEC-UruwfaOvTkXxrZds5hfcj8TNtzM6wOUAOy4s/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9yZWNl/aXRhdG9kYWhvcmEu/Y29tLmJyL3dwLWNv/bnRlbnQvdXBsb2Fk/cy8yMDI2LzA1L3F1/aW5kaW0tMjUwNS0x/MDI0eDY4My53ZWJw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-integral', 'Pão integral', 'Paes', '2009-12-07', 'Pão Integral.', '{"Sal":"2% - 60g","Água":"58% - 1740g","Reforcador":"1% - 30g","Fermento fresco":"3% - 90g","Farinha de trigo especial":"50% - 1500g","Farinha de trigo integral":"50% - 1500g"}', NULL, 'Coloque na masseira todos os ingredientes secos deixe bater por 1 minuto, e em seguida coloque a água e deixe bater por mais 5 minutos, ou até ficar lisa e homogênea, após bater coloque a massa sobre uma mesa untada com óleo e corte a massa em pedaços de 500 gramas e enrole como se enrola rocambole   de deixe descansar para crescer em forma para pão de forma  até a borda da forma e leve ao forno por mais ou menos 30 minutos a uma temperatura de 200 graus com vapor.', '', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8d2hvbGUlMjB3aGVhdCUyMGJyZWFkfGVufDB8fHx8MTc4NTE3NDg5Nnww&ixlib=rb-4.1.0&q=80&w=400', 'whole wheat bread');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-agua-e-sal', 'Biscoito água e sal', 'Massas', '2009-12-02', 'Biscoito tipo Cream Cracker.', '{"Sal":"2% - 20g","Ovos":"3% - 30g","Açúcar":"2% - 20g","Margarina":"3% - 30g","Farinha de trigo":"100% - 1000g"}', NULL, 'Coloque na batedeira ou na masseira todos os produtos de deixe bater mais ou menos 5 minutos ou até obter uma massa lisa e homogênea.  Coloque a massa sobre uma mesa  levemente untada com óleo estique a massa e com um rolo e corte com um cortador redondo. Arrume em uma bandeja levemente untada dom óleo sobre o regime de arrumação de sua escolha e leve ao forno por mais ou menos 15 minutos a uma temperatura de 200 graus.', '', 'https://images.unsplash.com/photo-1442604699113-7d805614c476?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8Y3JlYW0lMjBjcmFja2VyfGVufDB8fHx8MTc4NTE3NDI1MXww&ixlib=rb-4.1.0&q=80&w=400', 'cream cracker');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-de-bomba', 'Massa de bomba', 'Massas', '2009-11-30', 'Massa Bmba Pronta pra esplodir em sabor.', '{"Sal":"1% - 6g","Ovos":"167% - 1002g","Água":"167% - 1002g","Margarina":"83% - 498g","Farinha de trigo":"100% - 600g"}', NULL, 'Coloque em uma panela margarina sal e água e deixe ferver mexendo com uma colher de pau, acrescente a farinha e deixe cozinhar, após leve para batedeira acrescentando os ovos lentamente. Use um saco ou manga de confeitar  com bico 8B e modele em bandeja levemente untada com óleo com tamanho aproximado de 7 centímetros, e leve ao forno por mais ou menos ou menos 20 minutos a uma tempera 200 graus sem vapor.', '', 'https://imgs.search.brave.com/TSHly1c_ivABuXL7N7uOdyhl9tcPpYqWRf2yRSAhu0w/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly93d3cu/ZG9uYWJlbnRhcHJv/Zmlzc2lvbmFsLmNv/bS5ici93cC1jb250/ZW50L3VwbG9hZHMv/MjAyMy8xMi9zaXRl/LWptYWNlZG8tcmVj/ZWl0YS1tYXNzYS1k/ZS1ib21iYS5qcGc', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-flora', 'Massa Flora', 'Paes', '2009-11-30', 'Massa Boa para tortas e outras receitas. ', '{"Gema":"10% - 150g","Açúcar":"33% - 495g","Margarina":"67% - 1005g","Farinha de trigo":"100% - 1500g","Essência de limão":"QB"}', NULL, 'Coloque a farinha sobre a mesa e abra uma cova,  e ponha  o açúcar, a margarina e a essência de limão no meio, e misture com as mãos até formar uma massa lisa e homogênea (o aspecto da massa e semelhante ao da massa de coxinha).  Arrume a massa em formas de empada com camadas finas de fure cada uma com um garfo e leve ao forno por mais ou menos 15 minutos   a  uma temperatura de 180° graus.', '', 'https://imgs.search.brave.com/eFQYZMVZrUIYZlcCcQ6N1QuLdCFMoHfHTLh4q3crJOM/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9jZG4w/LnR1ZG9yZWNlaXRh/cy5jb20vcHQvcG9z/dHMvOC83LzcvbWFz/c2FfZmxvcmFfZG9j/ZV8zNzc4X3Bhc29f/M182MDAuanBn', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-de-fuba', 'Bolo de fubá', 'Bolos', '2009-11-30', 'Tradicional Bolo de Fubá. ', '{"Ovos":"88% - 792g","Fubá":"100% - 900g","Leite":"133% - 1197g","Açúcar":"111% - 999g","Erva doce":"5% - 45g","Margarina":"33% - 297g","Farinha de trigo":"24% - 216g","Fermento em po quimico":"6% - 54g"}', NULL, 'Junte a margarina, açúcar, leite e a erva doce e leve ao fogo para ferver, e quando ferver junte o fubá e deixe cozinhar muito bem. Após coloque na batedeira  e acescente os ovos de vagar e depois a farinha e o fermento   e deixe bater na terceira velocidade até obter a massa no ponto certo. Coloque a massa em um tabuleiro untado com margarina e polvilhado com farinha, e  leve ao forno por mais ou menos 25 minutos a uma temperatura de 200 graus.', '', 'https://imgs.search.brave.com/qRQic50NE3KhvizYq7e-kewmsImArrWZKUa08O40k2Q/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9zdGF0/aWMuaXRkZy5jb20u/YnIvaW1hZ2VzLzY0/MC0zNjAvNmU1Njhj/OTYzMjZhZTQ3ZDdh/NzViZjlkMmU5NmJi/NjAvYm9sby1kZS1m/dWJhLXNpbXBsZXMu/anBn', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-de-cebola-ou-queijo', 'Biscoito de cebola ou queijo', 'Bolos', '2009-11-25', 'Ótima opção de biscois apra fazer em casa.', '{"Sal":"2% - 10g","Gema":"6% - 30g","Margarina":"60% - 300g","Farinha de trigo":"100% - 500g","Queijo tipo parmesão ou cebola":"10% - 50g"}', NULL, 'Coloque a farinha de trigo sobre uma mesa e abra uma cova e coloque os ingredientes e faça uma massa lisa e homogênea. Modele e coloque em tabuleiro sem untar e pinte com gema de ovo e polvilhe queijo ralado por cima. Leve ao forno mais ou menos por 10 minutos ou até dourar a uma temperatura de 170° graus.', '', 'https://imgs.search.brave.com/yc0vSUjla3lBVM_UAILXIfQsP2o7rXOCgBciuCdY5Qw/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9uYW1p/bmhhcGFuZWxhLmNv/bS93cC1jb250ZW50/L3VwbG9hZHMvMjAx/NC8wNi9iaXNjb2l0/by1kZS1jZWJvbGEt/Mi5qcGc', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-folhada', 'Massa folhada', 'Massas', '2009-11-25', 'Massa Folhada para salgados e doces!', '{"Sal":"2% - 25g","Água":"64% - 800g","Farinha de trigo":"100% - 1250g","Margarina folhada":"80% - 1000g"}', NULL, 'Coloque a farinha sobre a mesa e faça uma cova e coloque o sal, Corte  a margarina em cubinhos adicione a massa e misture muito bem com as mãos até formar uma massa lisa e homogênea . Estique a massa e dê 3 voltas de 3 e depois mais quantas forem necessárias para a margarina se incorporar totalmente na massa, e deixe a massa descansar por 30 minutos  coberta com um pano, modele e deixe descansar mais 30 minutos, pinte com gemas de ovo e leve ao forno por mais ou menos 10 minutos a uma temperatura de 180 graus.', '', 'https://imgs.search.brave.com/wYxDKDesY1EL2IaCeGRPVPNHilSvwr_UlpjdPhE8sMI/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9zdG9y/YWdlLmdvb2dsZWFw/aXMuY29tL2ltYWdl/bnNfdmlkZW9zX2dv/dV9jb29raW5nX3By/b2QvcHJvZHVjdGlv/bi9jb29raW5nL2Ny/b3BwZWRfdGVtcF8y/MTA2NDI4MjM1NTYw/ZWNjOWI2ZTVlNzEu/OTA4MDk2MDlfLmpw/Zw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-frape', 'Bolo frapê', 'Bolos', '2009-11-23', 'Bolo frapê um bolo bicolor. ', '{"Ovos":"47% - 705g","Leite":"63% - 945g","Açúcar":"81% - 1215g","Biscomil":"5% - 75g","Margarina":"31% - 465g","Chocolate em pó":"5% - 75g","Farinha de trigo":"100% - 1500g","Amido de milho biscomil":"5% - 75g","Fermento em po químico":"5% - 75g"}', NULL, 'Coloque em uma batedeira 250 gramas de farinha  margarina e açúcar e   acrescentar o restante dos ovos e bater até cremar. Acrescentar farinha fermento  e o amido deixando o leite por ultimo bata mais 5 minutos. Separe 1/3 da massa acrescente o chocolate e misture a mão para obter um bolo do tipo frapê coloque sem chocolate em uma forma de pão de forma e  o restante por cima  e leve ao forno mais ou menos 20 minutos a uma temperatura de 180° graus.', '', 'https://imgs.search.brave.com/8-OztnGA_knZU51X6GxGJXpjOr1shrWtrY1kkifuEfY/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9pbWcu/YmFuZC5jb20uYnIv/aW1hZ2UvMjAyMy8w/Ni8xNC9ib2xvLWZy/YXBlLWRhLWNhcm9s/ZS1jcmVtYS0xNzI3/NTBfNDAweDMwMC53/ZWJw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-areia-de-caiscais', 'Biscoito areia de caiscais', 'Bolos', '2009-11-16', 'Receita importada de 16_11_2009_biscoito_areia_caiscais.doc', '{"Açúcar":"40%","Margarina":"67%","Farinha de trigo":"100%"}', NULL, 'Coloque farinha de trigo sobre a mesa e façauma cova e coloque o açúcar e a margarina misture com as mãos até ficar uma massa homogênea faça bolas de 1 centímetro de diametro arrume em tabuleiro  levemente untada com óleo, leve ao forno por mais ou menos  15 minutos a uma temperatura 160 graus.', '', 'https://imgs.search.brave.com/dePQ51FXOVu3ZlKyIRnLbW4lbiM--c3nIUO43F6FE3I/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly93d3cu/Y29uZmVpdGVpcmFk/ZXN1Y2Vzc28uY29t/L3dwLWNvbnRlbnQv/dXBsb2Fkcy8yMDI1/LzAzL2FyZWlhc2Nh/c2NhaXMuanBn', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-de-champanhe', 'Biscoito de champanhe', 'Outros', '2009-11-16', 'Biscoito muiso usado em pavê.', '{"Ovos":"50% - 500g","Açúcar":"80% - 800g","Farinha de trigo":"100% - 1000g"}', NULL, 'Coloque na batedeira açúcar e Ovos e deixe bater mais ou menos 15 minutos na 3ª velocidade desligue a batedeira e vá acrescentando a farinha e mexer com mão. Coloque a massa em forma de biscoito de champanhe previamente untada com margarina e polvilhada com farinha,coloque açúcar cristal em cima dos biscoitos antes de assar, e leve ao forno por mais ou menos 8 minutos a uma temperatura de 200º graus', '', 'https://imgs.search.brave.com/l3C-esCYD8gYXDfLQANtEbfIUfPWSoucY_ntXuT_DAc/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly93d3cu/ZG9uYWJlbnRhcHJv/Zmlzc2lvbmFsLmNv/bS5ici93cC1jb250/ZW50L3VwbG9hZHMv/MjAyMy8xMi9zaXRl/LWptYWNlZG8tcmVj/ZWl0YS1iaXNjb2l0/by1jaGFtcGFuaGUu/anBn', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-de-queijo', 'Pão de queijo', 'Bolos', '2009-11-16', 'Receita importada de 16_11_2009_pao_de_queijo.doc', '{"Sal":"2.5% - 25g","Ovos":"30% - 300g","Margarina":"20% - 200g","Queijo minas":"100% - 1000g","Polvilho azedo":"50% - 500g","Fécula de mandioca":"60% - 600g"}', NULL, 'Juntar em uma bacia queijo e o sal e misture e junte os ovos e amasse muito bem depois acrescente o polvilho e fécula  e amasse mais até ficar no ponto semelhante ao da coxinha. Faça bolas e empane os pães em queijo parmesão ralado e arrume em uma levemente untada com óleo e  leve ao forno mais ou menos 20 minutos a uma temperatura de 290  Graus.', '', 'https://images.unsplash.com/photo-1559141680-d0bd7bc5af84?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8cGFvJTIwZGUlMjBxdWVpam98ZW58MHx8fHwxNzg1MTkxNDE3fDA&ixlib=rb-4.1.0&q=80&w=400', 'Pão de queijo');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-de-milho-verde', 'Bolo de milho verde', 'Bolos', '2009-11-16', 'Bolo de milho verde. ', '{"Ovos":"200% - 1000g","Fubá":"100% - 500g","Açúcar":"170% - 850g","Margarina":"150% - 750g","Milho verde":"50% - 250g","Leite de coco":"70% - 350g","Farinha de trigo":"100% - 500g","Fermento em pó químico":"5% - 25g"}', NULL, 'Bata as claras  separadamente após esse processo retire da batedeira de deixe descansar. Coloque na batedeira margarina e açúcar na terceira velocidade mais ou  menos 5 minutos acrescente as gemas até obter um creme. Desligue a batedeira e acrescente com as mãos a farinha e o fubá e o fermento mexendo cuidadosamente para não deixar a massa dar liga. Acrescente o leite de coco e o milho e também as claras  e misture com as mãos. Terminado esse processo coloque em formas para bolo Inglês untadas com manteiga e polvilhadas com farinha, e leve ao forno a uma temperatura 180° graus mais ou menos 25 minutos.', '', 'https://imgs.search.brave.com/V3NWkteL_uw8iqdNdp7K1nRYGWiBghaNrWlY_ryCD_c/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9zdGF0/aWMuaXRkZy5jb20u/YnIvaW1hZ2VzLzY0/MC00MDAvN2ZlMDVj/MDdhYmMwNjNlYzA2/MGYzOTQyY2Y4ZTM5/MzMvMTkxMTIwLW9y/aWdpbmFsLmpwZw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('carinhoso', 'Carinhoso', 'Doces', '2009-11-16', 'Biscoito muito delicado.', '{"carinhoso":{"acucar":"50% - 500g","margarina":"100% - 1000g","coco-ralado":"30% - 300g","amido-de-milho":"100% - 1000g","farinha-de-trigo":"70% - 700g"},"caso-necessario":{"leite-de-coco":"20% - 200g"}}', NULL, 'Sobre um mesa misture o amido com  farinha abra uma cova e coloque açúcar e margaria amasse a obter uma  lisa (caso necessário coloque o leite de coco para não deixar a massa seca) divida a massa com um cortador redondo e  arrume a massa já modelada em uma bandeja e leve ao forno por mais ou menos 15 minutos  a  uma temperatura de 180 graus.', '', 'https://imgs.search.brave.com/2f9geWaaI7D_BTjBpkEXVHYSbFrSG4OLeCNC8VAbK0g/rs:fit:860:0:0:0/g:ce/aHR0cHM6Ly9uYW1p/bmhhcGFuZWxhLmNv/bS93cC1jb250ZW50/L3VwbG9hZHMvMjAx/NC8wOC9iaXNjb2l0/aW5oby1jYXJpbmhv/c28xLmpwZw', 'Carinhoso');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-folhada-de-processo-alemao', 'Massa folhada  (de processo Alemão)', 'Massas', '2009-11-12', 'Massa para doces e salgados.', '{"Sal":"1% - 13.5g","Água":"56% - 756g","Farinha de trigo":"100% - 1350g","Margarina para massa folhada":"74% - 999g"}', NULL, 'Coloque em uma masseira farinha sal e água e deixe bater até obter uma massa lisa e enxuta, e após deixe descansar mais ou menos  10 minutos. Depois corte  a massa em cruz e abra as quatro pontas e coloque no centro a margarina folhada e cubra com a massa e dê uma volta de  3 e deixe descansar 20 minutos. Dê  mais duas voltas de 3 e deixe descansarmais 10 minutos e dê mais uma volta de três e deixe descansar mais 10 minutos e dê mais uma volta de 3', '', 'https://imgs.search.brave.com/V3tELz7mxEujGZ4yIaZ07Firu06OjpAUl7EpAwKM2SM/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9saXJw/LmNkbi13ZWJzaXRl/LmNvbS8zMzQwNmM2/ZS9kbXMzcmVwL211/bHRpL29wdC9tYXNz/YStmb2xoYWRhLTE5/MjB3LmpwZw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-de-forma', 'Pão de forma', 'Paes', '2009-11-12', 'Pão (Plus Vita). ', '{"sal":"2% - 100g","agua":"54% - 2700g","ovos":"4% - 200g","acucar":"10% - 500g","margarina":"300g","reforcador":"1% - 50g","fermento-fresco":"6% - 300g","farinha-de-trigo":"100% - 5000g"}', NULL, 'Coloque na masseira todos os ingredientes secos de bater 1 minuto, depois coloque o restante dos ingredientes e deixe bater mais ou menos 5 minutos ou até a massa ficar lisa e homogênea. Retire a massa da masseira  e coloque sobre uma mesa untada com óleo e corte em pedaços de 550 gramas modele e ponha em forma para pão de forma e deixe descansar mais ou menos 120 minutos ou até dois dedos para encostar na tampa, e leve ao forno por mais ou menos 30 minutos a uma temperatura de 180 graus.', '', 'https://imgs.search.brave.com/cBxFXkmIKb-WG4vGbwz4uWVlzLcDx-43foN3MPGCF1U/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9tLm1l/ZGlhLWFtYXpvbi5j/b20vaW1hZ2VzL0kv/NjFQc0d0ZGNsckwu/anBn', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-de-batata', 'Pão de batata', 'Paes', '2009-11-12', 'Pão com uma das massas mais leves da panificação.', '{"massa-reforco":{"Sal":"2% - 80g","Ovos":"8% - 320g","Água":"30% - 1200g","Açúcar":"15% - 600g","Margarina":"8% - 320g","Batata cozida":"30% - 1200g","Farinha de trigo":"62.5% - 2500g"},"pao-de-batata-ingredientes-massa-esponja":{"Fermento":"6% - 240g","Farinha de trigo":"37.5% - 1500g"}}', NULL, 'Coloque 1 quilo e meio de farinha com todo o fermento da receita na masseira e faça uma  esponja e deixe descansar por 20 minutos coberta com plástico.', '', 'https://imgs.search.brave.com/KaB9jbRl8fcyMugL21gToYnnaYRwWUc8r1Kv56tI1Og/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9zMi1y/ZWNlaXRhcy5nbGJp/bWcuY29tL2pLNGg4/RDlLSjhiMUdrUzJW/LUh6VW1UeEU2QT0v/MHgwOjQ5NXgyNTAv/ODEweDAvc21hcnQv/ZmlsdGVyczpzdHJp/cF9pY2MoKS9zLmds/YmltZy5jb20vcG8v/cmMvbWVkaWEvMjAx/Mi8xMC8xMC8xOF8x/NF80MV81NjVfcmVj/ZWl0YV9wYW9fYmF0/YXRhLmpwZw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('panetone', 'Panetone', 'Paes', '2009-11-12', 'Muito comum no Natal.', '{"massa-de-reforco":{"Sal":"1% - 125g","Gema":"18% - 2250g","Água":"24% - 3000g","Pronamix":"40% - 5000g","Uvas-passa":"40% - 5000g","Farinha de trigo":"60% - 7500g","Frutas cristalizadas":"40% - 5000g"},"panetone-massa-esponja":{"Água":"22% - 2750g","Fermento":"7.2% - 900g","Farinha de trigo":"40% - 5000g"}}', NULL, 'Misture a primeira massa com a segunda e bata até ficar lisa e homogênea, e depois misture as  frutas ainda na masseira, e jogue toda massa em uma mesa untada com óleo, abra toda a massa e coloque as uvas passa no meio enrole como rocambole, e  corte em pedaços de 520 gramas e ponha na forma e deixe descansar por 3 horas ou até encostar  na borda da forma, e leve ao forno mais ou menos 40 minutos a uma temperatura de 180° graus.', '', 'https://imgs.search.brave.com/GBQ159k7sqVnFtbO7-RXZe1IOhf9Lt6q9lCZChAj4zQ/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9pbWcu/ZnJlZXBpay5jb20v/Zm90b3MtcHJlbWl1/bS9vLXBhbmV0b25l/LWUtYS1zb2JyZW1l/c2EtaXRhbGlhbmEt/dHJhZGljaW9uYWwt/cGFyYS1vLW5hdGFs/LWNob2NvdG9uZV83/MDIxNi0yODEwLmpw/Zz9zZW10PWFpc19o/eWJyaWQmdz03NDAm/cT04MA', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-de-polvilho-azedo', 'Biscoito de polvilho azedo', 'Doces', '2009-11-12', 'Derrete na boca.', '{"segunda-parte":{"Sal":"10% - 100g","Ovos":"10% - 100g","Leite":"100% - 1000g","Óleo":"100% - 1000g"},"primeira-parte":{"Água":"100% - 1000g","Polvilho azedo":"10% - 100g"}}', NULL, 'Junte a primeira parte leve ao fogo fazendo um farofa  e em seguida junte a primeira parte com a segunda parte em uma batedeira e deixe os ovos por ultimo  para dar ponto. Retire da batedeira e coloque em um saco ou manga de confeitar, e com um bico frisado ou liso pingue em um tabuleiro e leve ao forno a uma temperatura de  200° mais ou menos 20 minutos .', '', 'https://imgs.search.brave.com/DsrIF81QOl2LycevJggQKuG62jw9klMFO96bGiZXdlo/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly93d3cu/ZXN0YWRhby5jb20u/YnIvcmVzaXplci92/Mi9RSlpOV0MyUEVO/QlNaQkI3M0JQUUlH/UVFOTS5qcGVnP3F1/YWxpdHk9ODAmYXV0/aD0wOTlhZThmMTAx/M2U4OWU1NjE2ODg2/ZTI0MDlkNjk5NDlk/NjExZmIxOTJkMzRi/ZTcxMDMxZDkxZDdj/YzFjNjIxJndpZHRo/PTcyMCZoZWlnaHQ9/NDEwJmZvY2FsPTQz/OSw1NTQ', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-marmore', 'Bolo mármore', 'Bolos', '2009-11-12', 'Bonito por dentro e gostoso.', '{"Ovos":"150% - 500g","Açúcar":"100% - 500g","Margarina":"100% - 500g","Chocolate em pó":"10% - 50g","Farinha de trigo":"100% - 500g","Fermento em pó químico":"5% - 25g"}', NULL, 'Bata as claras separadamente retire do tacho e reserve. Junte a gema e o açúcar e acrescente a margarina aos poucos até obter uma massa lisa e homogênea. Acrescente a farinha e o fermento e misture com as mãos acrescente a claras e  continue mexendo manualmente. Separe um 1/3 da massa acrescente o chocolate, depois coloque a primeiro a massa sem chocolate em uma forma de para pão de forma e    e em seguida o restante e leve ao forno por mais ou menos 25 minutos a uma temperatura de 180° graus.', '', 'https://imgs.search.brave.com/PhHeFbm-OhpirDdQKubzeonp6twQg5KCp0WJtSxRBcA/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9ib2xv/c3BhcmF2ZW5kZXIu/Y29tL3dwLWNvbnRl/bnQvdXBsb2Fkcy8y/MDE5LzExL2JvbG8t/bSVDMyVBMXJtb3Jl/LXplYnJhLmpwZw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('maria-mole', 'Maria mole', 'Massas', '2009-11-11', 'Tradicional doce. ', '{"Água":"50% - 500g","Açúcar":"100% - 1000g","Margarina":"QB","Coco ralado":"40% - 400g","Gelaina neutra":"5% - 50g"}', NULL, 'Hidrate a gelatina da receita com água. Coloque em uma batedeira ainda quente juntamente com o açúcar e deixe bater mais ou menos 20 minutos ou até que não caia da colher. Unte uma mesa ou bandeja e com saco de confeitar  entenda a massa mais ou menos sete centímetros. Deixe secar por mais ou menos 1 hora e depois passar no coco ralado.', '', 'https://imgs.search.brave.com/j0j7QVU9aduF1nDFHtAvJ9vSqxs6NXrkUUqUw6FwgRk/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9jb21p/ZGluaGFzZG9jaGVm/LmNvbS93cC1jb250/ZW50L3VwbG9hZHMv/MjAxNi8wNi9NYXJp/YS1tb2xlLUNhc2Vp/cmEuanBn', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('minuta-de-chocolate', 'Minuta de chocolate', 'Outros', '2009-11-09', 'Mais uma versão daquele gostinho de chocolate.', '{"Ovos":"25% - 250g","Açúcar":"35% - 350g","Margarina":"30% - 300g","Chocolate em pó":"20% - 200g","Farinha de trigo":"100% - 1000g","Fermento em pó químico":"5% - 50g"}', NULL, 'Bata o açúcar com a margarina até formar um creme e em seguida coloque a farinha, o chocolate, o fermento todos misturados deixando por ultimo os ovos para dar ponto cortar pedaços de 30 gramas e faça bolas e passe no açúcar cristalizado e', '', '', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-doce', 'Pão doce', 'Paes', '2009-11-09', 'Dipensa apresentação.', '{"pao-doce":{"Sal":"2% - 100g","Ovos":"6% - 300g","Água":"50% - 2500g","Açúcar":"20% - 1000g","Fermento":"6% - 300g","Margarina":"8% - 400g","Reforcador":"1% - 50g","Farinha de trigo":"100% - 5000g"},"creme-para-pao-doce":{"Leite":"100% - 500g","Corante":"QB","Farinha":"40% - 200g"}}', NULL, 'Coloque todos os ingredientes secos na masseira e deixe bater 1 minutos, em seguida coloque a água e deixa bater 5 minutos. Após bater coloque a massa sobre uma mesa untada com óleo e corte em pedaços de 2 quilos e passe na cortadora para pães pequenos em corte em pedaços de 300 gramas para diversos. Modele  e arrume em bandeja levemente untada com óleo  sobre o regime de arrumação 10 por 3 caso os pães  sejam pequenos, pinte os pães com gema de ovo e leve ao armário e deixe descansar por mais ou menos 120 minutos ou até dobrar de tamanho, antes de levar ao forno coloque recheio externo	 e abertura, leve  para o forno por mais ou menos 20 minutos a uma temperatura de   160 graus.\n\nLeve ao fogo 500 gramas de Leite e 200 gramas de açúcar uma pitada de corante deixar ferver. Reserve 200 gramas de farinha e 200 gramas de açúcar e misture vigorosamente quando o leite começar a ferver para não empelotar.', '', 'https://imgs.search.brave.com/ZHv5tGwq-SP3R0zpnw1smjZE8bAnQ2Qw79JkISb2TVI/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9wYWVz/bm92b3Jpby5jb20u/YnIvd2ViL2ltYWdl/L3Byb2R1Y3QuaW1h/Z2UvOTIvaW1hZ2Vf/MTAyNC9QJUMzJTgz/TyUyMERPQ0UlMjBD/T0xFR0lBTCUyMERF/JTIwQ1JFTUU_dW5p/cXVlPWIwY2U3OGI', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('brevidade', 'Brevidade', 'Bolos', '2009-11-05', 'Bolo leve e gostovo.', '{"Ovos":"25% - 375g","Leite":"50% - 750g","Açúcar":"40% - 600g","Essência":"QB","Margarina":"40% - 600g","Amido de milho":"100% - 1500g","Fermento químico em pó":"1.4% - 21g"}', NULL, 'Coloque em uma bacia todos os ingredientes deixando o leite por ultimo para estabelecer o ponto adequado da massa, Bata a vá adicionando o leite até ela chegar no ponto, e em seguida use um saco ou  manga de confeitar com bico liso ou frisado para arrumar a massa em um tabuleiro levemente untado com óleo, após ter terminado todos os processos anteriores leve a massa ao forno mais ou menos 20 minutos a uma temperatura de 180 graus.', '', 'https://imgs.search.brave.com/Ja5w4RafwCmwNCmqMONxGqCBV8yvjcyJFGGebp7IspQ/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9zdGF0/aWMuaXRkZy5jb20u/YnIvaW1hZ2VzLzY0/MC00MDAvMzczMzgw/NWJlOTI2NmExNDIw/ZTYxNGU0MjY2OTI4/ODEvMTE0OTUyLW9y/aWdpbmFsLmpwZw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-amanteigado', 'Biscoito amanteigado', 'Massas', '2009-11-04', 'Um dos Biscoitos mais gostoso da culinária. ', '{"Ovos":"27.3%","Açúcar":"45.4%","Margarina":"72.8%","Farinha de trigo":"100%"}', NULL, '1. coloque na batedeira açúcar e margarina deixe bater 15 minutos  ou até cremar . 2. Diminua a velocidade  da batedeira e coloque os ovos e deixe bater por 3 minutos. 3. Depois desligue a batedeira coloque o restante dos ingredientes e deixe dar liga. 4. Após ponha a massa em um saco de confeitar com bico 8B, e arrume em bandeja levemente untada com óleo. 5. Leve  ao forno por mais ou menos  10 minutos a uma temperatura  de 180º.', '', 'https://imgs.search.brave.com/P5yD7rlQ03UkB3bYT6T-qCw5GewG1PEfmJE4acQ5FXc/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9zdGF0/aWMuaXRkZy5jb20u/YnIvaW1hZ2VzLzY0/MC00MDAvMWU1MjQ1/YmEwYWJkOTEyMThj/OWU0OWNmNWUwOWE2/YzkvMzQzODc2LW9y/aWdpbmFsLmpwZw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('rocambole', 'Rocambole', 'Outros', '2009-11-04', 'Receita importada de rocambole_04_11_2009.doc', '{"Ovos":"100%","Açúcar":"50%","Farinha de trigo":"50%"}', NULL, '1. Coloque   em uma batedeira os ovos e o açúcar e deixe bater por 15 mintos na 3ª velocidade. 2. Desligue a batedeira e coloque o restante dos ingedientes* e bata com as mão vigorosamente. 3. Coloque em uma mesa e espalhe em papel manteiga. 4. leve ao forno por mais ou menos 5 minutos a uma temperatura de 180°.', '', 'https://imgs.search.brave.com/4UeuLvVilbQWI_V1UQoAscBxc9efRELGt0AP7l-X9Ak/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9uYW1p/bmhhcGFuZWxhLmNv/bS93cC1jb250ZW50/L3VwbG9hZHMvMjAy/My8xMC9Sb2NhbWJv/bGUtZGUtZG9jZS1k/ZS1sZWl0ZS0zLndl/YnA', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('broa-aerosa', 'Broa aerosa', 'Paes', '2009-11-04', 'Umabroa com gosto delicado.', '{"Sal":"1.3%","Fuba":"50%","Ovos":"200%","Leite":"250%","Açúcar":"37.5%","Erva doce":"5%","Margarina":"100%","Farinha de trigo":"100%"}', NULL, '1. Coloque para ferver o leite, margarina sal  e o  Açúcar e a erva doce. 2. Misture a farinha de trigo com fubá na bacia da batedeira a parte. 3. Quando ferver o leite misture com os ingredientes que estão na bacia e deixe bater trinta segundos. 4. desligue  a batedeira coloque os ovos e deixe bater por mais 5 minutos ou até formar uma massa homogênea. 5. Deligue a batedeira e com a colher ou saco de confeitar, faça bolas de 30 gramas passe no fubá e  arrume em bandeja untada com óleo. 6. Leve ao forno por mais ou menos 20 minutos a uma temperatura 180°', '', 'https://imgs.search.brave.com/kQcRAFlmgFQb0k7XVSpRKUfYf4l6LVo_P43A8E8J6OU/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly92aXRh/dC5jb20uYnIvcmVj/ZWl0YXMvaW1hZ2Vz/L3JlY2lwZXNoYW5k/bGVyLmpwZz9pZD01/NzY3OSZ0aXBvPXIm/ZGVmYXVsdD1zJmlt/cz1maXQtaW4vNDE0/eDI3NS9maWx0ZXJz/OnF1YWxpdHkoNjAp', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-ingles', 'Bolo Inglês', 'Bolos', '2009-11-03', 'Receita importada de bolo_ingles_03_11_2009.doc', '{"Ovos":"45%","Amido":"7%","Leite":"63%","Açúcar":"82%","Margarina":"32%","Farinha de trigo":"100%","Fermento pó químico":"4%"}', NULL, '1. Coloque em uma batedeira na terceira velocidade margarina e açúcar por mais ou menos 15 minutos ou até cremar 2. reduza a velocidade da batedeira para primeira, e coloque o restante dos ingredientes deixando o leite por ultimo . 3. Após os ingredientes misturados deixe bater por mais 5 minutos. 4. Tendo a massa atingido o ponto coloque em forma para bolo Inglês. 5. Asse no forno a 180°  por mais ou menos 15 minutos.', '', 'https://imgs.search.brave.com/0CRG6uuW9S_K_yTdYj7CmEvFK-iPxjlC6flZt5dgzGQ/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9pMC53/cC5jb20vY2Fyb2xm/aW9yZW50aW5vLmNv/bS5ici93cC1jb250/ZW50L3VwbG9hZHMv/MjAxNS8xMC9ib2xv/LWluZ2xlcy1pbWFn/ZW0tZGVzdGFxdWUu/anBnP3Jlc2l6ZT03/NjgsNTAwJnNzbD0x', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('sequilho-de-coco', 'Sequilho de coco', 'Doces', '2009-11-03', 'Biscoito que derrete na boca.', '{"acucar":"50%","margarina":"100%","coco-ralado":"30%","leite-de-coco":"QB","amido-de-milho":"100%","farinha-de-trigo":"70%"}', NULL, '1. junte a farinha de trigo, amido de milho e açúcar em uma bacia ou na mesa e misture bem com as mão 2. Depois coloque a margarina e o coco ralado  e continue misturando com mãos até ficar lisa e homogênea. 3. Faça bolas pequenas e arrume em bandejas sobre o regime de arrumação e marque os biscoitos com um garfo . 4. Leve ao forno a 180° (cento e oitenta gráus)  mais ou menos 15 minutos .', '', 'https://imgs.search.brave.com/SlLinYRcg4fJO1W_6xB-3uUQ6KykNV6y7LidJoUCNvc/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9tZWxl/cGltZW50YS5jb20v/d3AtY29udGVudC91/cGxvYWRzLzIwMTYv/MDYvU2VxdWlsaG9z/LWRlLWNvY28tQmFp/eGEtMS0xMDI0eDY4/My5qcGc', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-frances', 'Pão francês', 'Paes', '2009-10-29', 'Pão nosso de cada dia.', '{"Sal":"2%","Água":"53%","Fermento":"3%","Reforcador":"1%","Farinha de trigo":"100%"}', NULL, 'Coloque na masseira todos os ingredientes secos deixe bater por 2 minuto, após bater coloque  o restante dos ingredientes de deixe bater mais 5 minutos ou até ficar lisa e homogênea,   depois de bater coloque a massa em uma mesa untada com óleo e corte em pedaços de 2 quilos,  após corte e  modele a massa para por  nas formas para pão francês (Grades) com as costuras voltadas para baixo e deixe descansar por mais ou menos 120 minutos, após o tempo adequado de descanso leve  ao forno por mais ou menos 15 minutos com vapor .', '', 'https://imgs.search.brave.com/ZC2l7PoEaq0buj1KEBbSNa8sRqM-gTMSvcHFPlRpRTA/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly90My5m/dGNkbi5uZXQvanBn/LzA1LzQ4LzQ3LzUy/LzM2MF9GXzU0ODQ3/NTI0NV9ZMDQyZTN6/d3RqRTQzQmpxYlk4/OGRLbWdqbnM2WnNm/Mi5qcGc', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-para-pizza', 'Massa para pizza', 'Massas', '2009-10-29', 'Mamamia.', '{"Sal":"2%","Ovos":"2%","Água":"58%","Farinha":"100%","Açúcar":"2%","Fermento":"3%","Margarina":"3%"}', NULL, 'Coloque todos os ingredientes secos na masseira e deixe bater por  1 minuto depois de bater coloque o restante dos ingredientes de deixe bater novamente por mais  5 minutos  ou até a massa ficar lisa e homogênea, estando a massa  lisa e homogênea retire da masseira e coloque sobre uma mesa  levemente untada com  óleo e corte em pedaços de acordo com a bandeja que será usada para levar a massa ao forno, modele e fure com um garfo , e deixe descansar por mais ou menos 90 minutos, após descansar leve ao forno por 4 minutos a uma temperatura de 180 graus retire embale e guarde.', '', 'https://imgs.search.brave.com/0q0YCPSn5nlwArqul8QiPkCUnOsP9tbfF-HPfNtGvwc/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly93d3cu/cmVjZWl0YXNuZXN0/bGUuY29tLmJyL3Np/dGVzL2RlZmF1bHQv/ZmlsZXMvc3R5bGVz/L2Nyb3BwZWRfcmVj/aXBlX2NhcmRfbmV3/L3B1YmxpYy9zcmhf/cmVjaXBlcy83MDMx/NTYwZTIyNjdhOTYx/NGZiMWNiZDcyNjBk/Y2RhNS5qcGc_aXRv/az0xRjNsa1ZmdA', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-suico', 'Pão suíço', 'Massas', '2009-10-28', 'Pão com a massa fina.', '{"Sal":"2%","Ovos":"8%","Água":"54%","Farinha":"100%","Açúcar":"10%","Fermento":"6%","Margarina":"6%","Reforcador":"1%"}', NULL, 'Coloque Todos os ingredientes secos na masseira  e deixe bater por um minuto, depois de bater coloque o restante dos ingredientes e deixe bater por  mais 5 minutos  ou até ficar lisa  e homogênea. Terminado este processo coloque a massa em uma mesa untada com óleo e divida em pedaços  de dois quilos  e depois divida a massa novamente em   30 pedaços, modele e arrume em uma bandeja sobre o regime 10 por 3 (3 colunas e 10 fileiras), já arrumado  deixe descansar em um armário, Ou coberto com um pano ou saco plástico por mais ou menos 120 minutos. Após descansar leve ao forno mais ou menos   20 minutos a uma temperatura de 180 graus,', '', 'https://imgs.search.brave.com/UNGxgpWXbczndgqozxqn46plEFKdH0Wug5Slb9Sw6Vg/rs:fit:0:180:1:0/g:ce/aHR0cHM6Ly9wZWNw/YW8uY29tLmJyL3dw/LWNvbnRlbnQvdXBs/b2Fkcy8yMDE1LzA4/L3N1aWNvLWJhbm5l/ci5qcGc', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-mae-benta', 'Bolo mãe Benta', 'Bolos', '2009-10-27', 'Mais umbolo gostoso.', '{"Ovos":"60%","Farinha":"100%","Açúcar":"75%","Margarina":"35%","Leite líquido":"50%","Fermento em pó":"5%"}', NULL, '	Coloque  em uma batedeira a margarina e açúcar, e deixe bater mais ou menos 15 minutos ou até a massa fique com um aspecto de creme, diminua a velocidade da batedeira coloque o restante dos ingredientes deixando o leite por último , após este processo aumente a velocidade da batedeira e deixe bater por mais 5 minutos. Estando a massa pronta use um saco de confeitar para colocar a massa em formas de papel de numero 0 (zero),depois leve ao forno por mais ou menos 15 minutos a uma temperatura de 180 graus.   \n', '', 'https://imgs.search.brave.com/Jdd2oOIuQn8gDe8eNKAt75nDaji5ZD34M-eSjxTOJ1c/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9kM3Zr/aTJpaWJ0M3lmMi5j/bG91ZGZyb250Lm5l/dC9yZWNlaXRhcy9p/bWFnZW5zL2ZvdG9z/LzEyYzUxNTJmLWQ1/YTEtNDE0OS04YzRl/LTNmZGE5NjliNjk5/NS53ZWJw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('brioche-industrial', 'Brioche industrial', 'Massas', '2009-10-22', 'Ideal ára salgado assados.', '{"Sal":"2%","Ovos":"6%","Água":"54%","Farinha":"100%","Açúcar":"2%","Fermento":"6%","Margarina":"6%","Reforcador":"1%"}', NULL, '	Coloque tos os ingredientes secos na masseira por 1 minuto ou até os ingredientes secos estiverem bem misturados,em seguida coloque o restante dos ingredientes e bater por mais 5 minutos ou até a massa ficar lisa e homogênea, em seguida coloque a massa em cima de uma mesa untada com óleo  e divida a massa em pedaços de de 1,2 Kg (um quilo e duzentos  gramas)   , depois divida cada pedaço de 1,2Kg em trinta bolas e arrume as bolas em uma bandeja untada com óleo sobre o regime 6 por 5. Depois dessas etapas deixe a massa descansar um armário  ou coberto com uma tampa ou pano. Após descansar a massa devidamente preparada leve ao forno pré aquecido aproximadamente por 10 minutos  a  uma temperatura de 180 graus.', '', 'https://imgs.search.brave.com/ejuHMne_sDOk4-1vect42MR4nTGTwTf_EWj8IqkJ9dE/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly90ZW1w/ZXJvZG9kaWEuY29t/LmJyL3dwLWNvbnRl/bnQvdXBsb2Fkcy8y/MDI0LzEyL2pvZWxo/by1kZS1wcmVzdW50/by1lLXF1ZWlqby1y/ZWNlaXRhLmpwZw', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('broa-cachambu-cavaca', 'Broa cachambú (cavaca)', 'Broas', '2009-10-22', 'Tradicional cavaca !!!', '{"Ovos":"30%","Fubá":"100%","Farinha":"100%","Açúcar":"100%","Erva-doce":"5%","Margarina":"60%","Fermento em pó":"5%"}', NULL, 'Coloque todos os ingredientes em uma bacia, e misture até a massa ficar lisa e homogênea. Após arrume sobre o regime 9 por 6 (9 fileiras e seis colunas ) em uma bandeja levemente untada com óleo em porções de aproximadamente 30 gramas. Leve ao forno por 15 minutos a uma temperatura de 180 graus.', '', 'https://imgs.search.brave.com/WteSImR720YUEkdASrkl_4wezSr3TjwhkwwRRhYIJc0/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9pbWcu/ZnJlZXBpay5jb20v/Zm90b3MtcHJlbWl1/bS9icm9hLWRlLW1p/bGhvLWJpc2NvaXRv/cy10cmFkaWNpb25h/aXMtYnJhc2lsZWly/b3NfNDM0MTkzLTIw/NzAuanBn', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('broa-de-milho', 'Broa de milho', 'Bolos', '2009-10-22', 'Receita importada de Broa_de_milho_22_10_2009.doc', '{"Sal":"1.5%","Ovos":"15%","Fubá":"20%","Água":"35%","Farinha":"100%","Açúcar":"15%","Fermento":"5%","Anti-mofo":"0.3%","Erva-doce":"1.5%","Margarina":"2.5%","Reforcador":"1.5%"}', NULL, 'Coloque todos os ingredientes secos na masseira e deixe bater por um minuto, em seguida colocar o restante dos ingredientes e deixar bater aproximadamente 5 minutos, ou até ficar lisa e homogênea. Após bater divida a massa em dois pedaços de 2 quilos, depois divida esses pedaços em 30 partes. Estando as massas divididas faça bolas e passe na água o no fubá, arrume-as em bandejas sobre o regime 6 por 5 (cinco colunas e seis fileiras) levemente untadas com óleo, e deixe descansar por aproximadamente120 minutos. Após descansar leve ao forno por 20 minutos a uma temperatura de 180 graus', '', 'https://imgs.search.brave.com/p4gkBPcptJODeH7jLlr6BdlIHaZegNNA7izcG6szWc0/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9hbW9w/YW9jYXNlaXJvLmNv/bS5ici93cC1jb250/ZW50L3VwbG9hZHMv/MjAyMy8wNS95dDA4/OF9icm9hLWRlLW1p/bGhvX3JlY2VpdGEt/ODQweDU0MC5qcGc', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-de-hamburguer', 'Pão de hambúrguer', 'Massas', '2009-10-20', 'Receita importada de Pao_de_hamburguer_20_10_2009.doc', '{"Ovos":"8%","Água":"53%","Farinha":"100%","Açúcar":"15%","Fermento":"6%","Margarina":"8%","Reforcador":"1%"}', NULL, 'Coloque todos os ingredientes secos na masseira, em seguida o restante, e deixe  bater 5 minutos ou até a massa ficar lisa. Retire a massa da masseira e coloque em uma mesa untada com óleo, em seguida divida a massa com um aparelho divisor em 30 pedaços,Arrume sobre o regime 6 por 5  e deixe descansar no armário pos aproximadamente 120 minutos ou até dobrar de tamanho, após descansar leve ao forno por 20 minutos a uma teperatura de 180 graus.', '', 'https://imgs.search.brave.com/v4dniAdoSIVzQAYl5eFXdpUvV7rBDnF9Rq2TpTcsafQ/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly9jZG4u/b2NlYW5zZXJ2ZXIu/Y29tLmJyL2xvamFz/L2FscXVpbWlhZnVu/Y2lvbmFsL3VwbG9h/ZHNfcHJvZHV0by9k/ZXNpZ24tc2VtLW5v/bWUtNjExNmJkYjAx/NDEwZS5wbmc', '');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('brioche-rapido', 'Brioche rápido', 'Paes', '2009-10-19', 'Receita importada de brioche_rapido_19_10_2009.doc', '{"esponja-de-reforco":{"Gema":"30g","Ovos":"50g","Farinha":"20% - 125g"},"brioche-rapido-esponja":{"Sal":"1.6% - 10g","Gema":"4.8% - 30g","Ovos":"8% - 50g","Água":"QB","Farinha":"80% - 500g","Açúcar":"12% - 75g","Fermento":"8%","Margarina":"75%"}}', NULL, 'Caso o o fermento seja do tipo seco, comece misturando a farinha o o fermente antes de por a água, estando o fermento e a farinha bem misturadas, junte os outro ingredientes faça uma massa homogênea  e  deixe descansar por aproximadamente 30 minutos . Depois junte o restante da farinha, mais açúcar, sal e margarina, e faça uma massa homogênea, não esqueça da água! Misture  a primeira massa com a segunda e abra   massa  com um rolo de pastel até ficar lisa e homogênea. Depois desse  processo todo, enrole a massa como  rocambole, e corte em pedaços de aproximadamente 30 gramas, arrume em um tabuleiro sobre o regime 9 por 6.Deixe descansar em um armário fechado ou coberto por um plástico por aproximadamente 90 minutos. Após descansar leve ao forno por 15 minutos na temperatura de 160 graus.', 'Processo massa esponja par aacelerar a fermentação.', 'https://imgs.search.brave.com/395y4yfSojcvaISz3jeYlxz1vaGATE5IJ8zxldEZ1mQ/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly93d3cu/ZW0uY29tLmJyL2Vt/Zm9jby93cC1jb250/ZW50L3VwbG9hZHMv/MjAyNi8wMi9DaGF0/R1BULUltYWdlLTI2/LWRlLWZldi4tZGUt/MjAyNi0yMF81M18y/Ni0xLTc1MHgzNzUu/cG5n', '');
